class ManageBookCRUDService_AutoGenerated {
  /*Creates a new book.*/
  createBook(
    callno: string,
    title: string,
    edition: string,
    author: string,
    publisher: string,
    description: string,
    isbn: string,
    copynum: number,
  ): boolean {
    /*Definition Start*/
    let obs: Book[] = l({
      logic: () =>
        getRepository(Book).filter(
          (o: any) =>
            l({
              logic: () => o.CallNo === callno,
              description: "o.CallNo=callno",
            })
              .or({
                logic: () => o.ISBn === isbn,
                description: "o.ISBn=isbn",
              })
              .build().pass,
        ),
      description: "Book.allInstance()->select(o|o.CallNo=callnooro.ISBn=isbn)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => callno.length > 0,
        description: "callno.size()>0",
      })
        .and({
          logic: () => title.length > 0,
          description: "title.size()>0",
        })
        .and({
          logic: () => edition.length > 0,
          description: "edition.size()>0",
        })
        .and({
          logic: () => author.length > 0,
          description: "author.size()>0",
        })
        .and({
          logic: () => publisher.length > 0,
          description: "publisher.size()>0",
        })
        .and({
          logic: () => description.length > 0,
          description: "description.size()>0",
        })
        .and({
          logic: () => isbn.length > 0,
          description: "isbn.size()>0",
        })
        .and({
          logic: () => copynum >= 0,
          description: "copynum>=0",
        })
        .and({
          logic: () => StandardOPs.isEmpty(obs),
          description: "obs.isEmpty()",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let ob: Book;
    return l({
      execute: () => (ob = new Book()),
      description: "ob.oclIsNew()",
    })
      .and({
        execute: () => (ob.CallNo = callno),
        description: "ob.CallNo=callno",
      })
      .and({
        execute: () => (ob.Title = title),
        description: "ob.Title=title",
      })
      .and({
        execute: () => (ob.Edition = edition),
        description: "ob.Edition=edition",
      })
      .and({
        execute: () => (ob.Author = author),
        description: "ob.Author=author",
      })
      .and({
        execute: () => (ob.Publisher = publisher),
        description: "ob.Publisher=publisher",
      })
      .and({
        execute: () => (ob.Description = description),
        description: "ob.Description=description",
      })
      .and({
        execute: () => (ob.ISBn = isbn),
        description: "ob.ISBn=isbn",
      })
      .and({
        execute: () => (ob.CopyNum = copynum),
        description: "ob.CopyNum=copynum",
      })
      .and({
        execute: () => getRepository(Book).push(ob),
        description: "Book.allInstance()->includes(ob)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ManageBookCRUDService_AutoGenerated };

